INSERT INTO public.events (id, title, description, date, location, institution, image_data_url, category_id, requires_registration, published, status, hours, conditions, capacity, registered_count, wilaya_code, commune, is_demo) VALUES ('demo-evt-setif-aines', 'Journée Intergénérationnelle de Soutien et Écoute des Personnes Âgées et Isolées', 'Journée réussie au foyer de personnes âgées de Sétif. 35 bénévoles ont accompagné 70 aînés lors d''une sortie conviviale au Parc d''Attraction, d''un dépistage tension/diabète et d''un récital poétique traditionnel.', '2026-10-25', 'Foyer des Personnes Âgées & Parc d''Attraction, Sétif', 'Croissant-Rouge Algérien — Comité de Sétif', 'https://images.unsplash.com/photo-1576765608535-5f04d1e3f289?w=1200&q=80', 'sante', TRUE, TRUE, 'completed', '09:30 - 16:30', 'Événement clôturé avec succès.', 35, 35, 19, 'Sétif', TRUE) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, date = EXCLUDED.date, status = EXCLUDED.status;
INSERT INTO public.events (id, title, description, date, location, institution, image_data_url, category_id, requires_registration, published, status, hours, conditions, capacity, registered_count, wilaya_code, commune, is_demo) VALUES ('demo-evt-eulma-sensibilisation', 'Atelier Pratique de Sensibilisation Écologique et Valorisation des Déchets Commerciaux', 'Session interactive au cœur du grand pôle commercial d''El Eulma : sensibilisation des commerçants et lycéens au recyclage des cartons, plastiques d''emballage et gestion rationnelle des ressources.', '2026-11-30', 'Maison de Jeunes Mohamed Belouizdad, Cité 19 Juin, El Eulma', 'Direction de la Jeunesse et des Sports — Antenne El Eulma', 'https://images.unsplash.com/photo-1532996122724-e3c354a0b15b?w=1200&q=80', 'environnemental', TRUE, TRUE, 'open', '14:00 - 17:30', 'Ouvert à tous. Des kits de documentation éco-responsable seront remis aux participants.', 80, 41, 19, 'El Eulma', TRUE) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, date = EXCLUDED.date, status = EXCLUDED.status;
INSERT INTO public.events (id, title, description, date, location, institution, image_data_url, category_id, requires_registration, published, status, hours, conditions, capacity, registered_count, wilaya_code, commune, is_demo) VALUES ('demo-evt-bejaia-don-sang', 'Grande Collecte Solidaire de Don de Sang : « Une Goutte pour la Vie »', 'Caravane mobile de transfusion sanguine en coordination avec le Centre de Transfusion Sanguine (CTS) et le CHU Khellil Amrane pour approvisionner les urgences hospitalières de Béjaïa et d''Akbou.', '2026-12-10', 'Place du 1er Novembre (ex-Place Gueydon), Béjaïa-Ville', 'CHU Khellil Amrane & CTS Béjaïa', 'https://images.unsplash.com/photo-1615461066841-6116e61058f4?w=1200&q=80', 'sante', TRUE, TRUE, 'open', '08:30 - 16:30', 'Être âgé de 18 à 65 ans, peser plus de 50 kg et être en bonne santé générale. Collation énergétique offerte.', 120, 78, 6, 'Béjaïa', TRUE) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, date = EXCLUDED.date, status = EXCLUDED.status;
