INSERT INTO public.news (id, title, description, content, category, category_id, date, image_data_url, featured, published, wilaya_code, commune, is_demo) VALUES ('demo-news-bejaia-gouraya', 'Béjaïa : Mobilisation record pour la préservation du Parc National de Gouraya', 'Plus de 300 jeunes bénévoles se sont rassemblés ce week-end pour reboiser les crêtes et nettoyer les sentiers historiques du Cap Carbon.', 'La ville de Béjaïa a vibré au rythme d''une formidable synergie citoyenne. À l''initiative de la plateforme solidaire « Yed fel yed » et en étroite coordination avec la Conservation des Forêts de la Wilaya de Béjaïa, des centaines de jeunes venus de Béjaïa-Ville, d''Akbou, d''Amizour et de Sidi-Aïch ont uni leurs forces.
INSERT INTO public.news (id, title, description, content, category, category_id, date, image_data_url, featured, published, wilaya_code, commune, is_demo) VALUES ('demo-news-setif-innovation', 'Sétif : Inauguration du Hub de l''Innovation Civique et du Bénévolat Numérique', 'Un espace moderne dédié aux projets technologiques solidaires et aux solutions d''entraide communautaire ouvre ses portes à Sétif.', 'Le Centre des Loisirs Scientifiques de Sétif a inauguré ce lundi son tout nouveau pôle d''innovation civique. Ce projet ambitieux met à disposition des jeunes développeurs, secouristes et coordinateurs associatifs des imprimantes 3D, du matériel de télécommunication d''urgence et des postes de travail connectés.
INSERT INTO public.news (id, title, description, content, category, category_id, date, image_data_url, featured, published, wilaya_code, commune, is_demo) VALUES ('demo-news-eulma-caravane', 'El Eulma : Commerçants et jeunesse solidaire préparent les convois du grand froid', 'Une vaste alliance caritative rassemble 500 kits thermiques et denrées pour soutenir les familles isolées des Hauts Plateaux.', 'À l''approche des premières vagues de froid sur les Hauts Plateaux, la ville d''El Eulma montre l''exemple d''une grande cohésion humaine. Les associations locales, soutenues par les commerçants du grand pôle marchand et les jeunes adhérents de la plateforme Yed fel yed, ont constitué un stock stratégique de couvertures, poêles de sécurité et produits de première nécessité.
INSERT INTO public.news (id, title, description, content, category, category_id, date, image_data_url, featured, published, wilaya_code, commune, is_demo) VALUES ('demo-news-akbou-secourisme', 'Akbou : Remise officielle des attestations aux 45 nouveaux secouristes certifiés', 'Une promotion exemplaire de jeunes secouristes formés aux gestes d''urgence prête serment au Complexe de Proximité de l''ODEJ.', 'Au terme d''un cycle de formation de six semaines validé par la Protection Civile, 45 jeunes volontaires d''Akbou et de la Soummam ont reçu leur brevet officiel de secourisme civique. Ils rejoignent immédiatement la réserve opérationnelle pour les missions d''assistance sur le terrain.', 'إسعاف وطوارئ', 'urgences', '2026-10-20', 'https://images.unsplash.com/photo-1516574187841-cb9cc2ca948b?w=800&q=80', FALSE, TRUE, 6, 'Akbou', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.news (id, title, description, content, category, category_id, date, image_data_url, featured, published, wilaya_code, commune, is_demo) VALUES ('demo-news-setif-marathon', 'Sétif : 1 200 participants attendus pour la 4e édition des Foulées Solidaires', 'Le sport au service du handicap et de la fraternité citoyenne sur le circuit du complexe 8 Mai 1945.', 'L''esplanade du stade du 8 Mai 1945 s''apprête à accueillir l''un des plus grands rassemblements sportifs et solidaires de la région est. Valides et athlètes handisport concourront côte à côte pour promouvoir l''inclusion active et lever des fonds d''équipements adaptés.', 'رياضة ومجتمع', 'social', '2026-10-15', 'https://images.unsplash.com/photo-1552674605-db6ffd4facb5?w=800&q=80', FALSE, TRUE, 19, 'Sétif', TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.news (id, title, description, content, category, category_id, date, image_data_url, featured, published, wilaya_code, commune, is_demo) VALUES ('demo-news-eulma-arbres', 'El Eulma : Aménagement participatif d''un nouveau square vert à la Cité 19 Juin', 'Les familles et les écoliers transforment un terrain vague en espace de détente arboré et convivial.', 'Grâce à l''initiative conjointe de la Maison de Jeunes Mohamed Belouizdad et des habitants du quartier, plus de 200 arbustes d''ornement et bancs restaurés ornent désormais la place centrale du quartier.', 'بيئة وتنمية', 'environnemental', '2026-10-10', 'https://images.unsplash.com/photo-1582213782179-e0d53f98f2ca?w=800&q=80', FALSE, TRUE, 19, 'El Eulma', TRUE) ON CONFLICT (id) DO NOTHING;
