INSERT INTO public.mission_reports (id, mission_id, mission_title, mission_type, author_id, author_name, author_role, wilaya_code, commune, date, summary, achievements, difficulties, participants_count, hours_spent, status, auditor_id, auditor_name, audit_notes, reward_points_granted, is_demo) VALUES ('demo-rep-01', 'demo-evt-01', 'Rapport d''intervention : Nettoyage & Dépollution Gouraya & Cap Carbon', 'event', 'demo-user-lead-01', 'Sofiane Belkacemi', 'mission_lead', 6, 'Béjaïa', '2026-10-18', 'Nettoyage intégral de la corniche et des sentiers de Cap Carbon. Évacuation de 3,2 tonnes de déchets triés vers le centre de recyclage.', 'Corniche du Cap Carbon entièrement dépolluée ; 320 sacs de déchets plastiques et canettes triés ; Sensibilisation directe auprès de plus de 150 visiteurs', 'Accès abrupt sur certains versants rocheux nécessitant un encadrement renforcé par les cordistes.', 42, 5, 'validated', 'demo-user-aud-01', 'Rachid Hamidi', 'Rapport audit conforme aux exigences du MJS. Fiches de présence et bordereaux de pesée des déchets certifiés.', 0, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mission_reports (id, mission_id, mission_title, mission_type, author_id, author_name, author_role, wilaya_code, commune, date, summary, achievements, difficulties, participants_count, hours_spent, status, auditor_id, auditor_name, audit_notes, reward_points_granted, is_demo) VALUES ('demo-rep-02', 'demo-evt-02', 'Rapport de plantation : 800 Arbustes Forêt Zenadia Sétif', 'event', 'demo-user-wil-19', 'Tarek Mansouri', 'wilaya_admin', 19, 'Sétif', '2026-10-25', 'Reboisement d''une parcelle touchée par les incendies passés. Plantation de 800 cèdres de l''Atlas et pins d''Alep avec arrosage initial.', '800 plants mis en terre avec tuteurs et paillage ; Mobilisation citoyenne exemplaire des familles de Sétif ; Partenariat opérationnel avec la Conservation des Forêts', '', 35, 6, 'validated', 'demo-user-aud-01', 'Rachid Hamidi', 'Attestation de conformité validée par les gardes forestiers de Sétif.', 0, TRUE) ON CONFLICT (id) DO NOTHING;
